import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { initDatabase } from './server/db.js';
import { authRouter } from './server/routes/auth.js';
import { policiesRouter } from './server/routes/policies.js';
import { weatherRouter } from './server/routes/weather.js';
import { claimsRouter } from './server/routes/claims.js';
import { payoutsRouter } from './server/routes/payouts.js';
import { auditRouter } from './server/routes/audit.js';
import { adminRouter } from './server/routes/admin.js';
import { systemRouter } from './server/routes/system.js';

async function startServer() {
  // 1. Initialize SQLite Database
  initDatabase();

  const app = express();
  const PORT = 3000;

  // Middleware
  app.use(express.json());

  // Section 26: Health and Monitoring endpoints
  app.use(systemRouter);

  // Android APK Direct Download Endpoint
  app.get(['/agrishield-insurance.apk', '/download/agrishield-insurance.apk', '/api/download/apk'], (req, res) => {
    const apkPath = path.join(process.cwd(), 'public', 'agrishield-insurance.apk');
    res.setHeader('Content-Type', 'application/vnd.android.package-archive');
    res.setHeader('Content-Disposition', 'attachment; filename="agrishield-insurance.apk"');
    res.sendFile(apkPath, (err) => {
      if (err) {
        res.status(404).json({ error: 'APK build file not found. Please run APK build script.' });
      }
    });
  });

  // REST API Routes
  app.use('/api/auth', authRouter);
  app.use('/api/policies', policiesRouter);
  app.use('/api/weather', weatherRouter);
  app.use('/api/claims', claimsRouter);
  app.use('/api/payouts', payoutsRouter);
  app.use('/api/audit-trail', auditRouter);
  app.use('/api/admin', adminRouter);

  // Vite middleware for development vs static build in production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`[AgriShield Server] running on http://0.0.0.0:${PORT}`);
  });
}

startServer().catch((err) => {
  console.error('[AgriShield Server] Startup Error:', err);
  process.exit(1);
});
